import type { HelpTopic, HelpImage, Parameter } from "../topics";

const shot = (path: string, caption: string): HelpImage => ({ path: `reference/${path}.png`, caption });
const feather: Parameter = ["Sfumatura", "Ammorbidisce il contorno. 0 dà un bordo netto ed è il valore predefinito dei nuovi strumenti; 1 usa tutta la zona di sfumatura disponibile. Un modificatore attenua il proprio effetto verso il campo invariato; uno strumento di pittura attenua il proprio contributo. Gli oggetti esistenti conservano il valore salvato."];
const edge: Parameter = ["Bordo: Fondi / Sostituisci", "Fondi mescola il nuovo vettore con quello esistente attraverso un bordo morbido. Sostituisci, invece, attenua il nuovo vettore verso la calma. L'interno netto usa il nuovo vettore in entrambe le modalità. Le celle di origine non definite restano trasparenti in entrambe le modalità."];
const size: Parameter = ["Dimensione e unità", "Diametro del pennello o larghezza del quadrato. px dà proporzioni sullo schermo costanti al momento della creazione; km / nm dà una distanza sul terreno. Lo zoom successivo non ridimensiona gli oggetti esistenti. L'unità scelta vale anche per gli altri controlli di dimensione dello strumento."];
const brushShape: Parameter = ["Forma del pennello: Cerchio / Quadrato", "Sceglie l'impronta trascinata lungo il gesto. Cerchio produce estremità arrotondate; Quadrato trascina impronte quadrate. Questa scelta di geometria è fissata dopo il disegno; l'animazione della forma può rimodellare un oggetto esistente."];
const speed: Parameter = ["Velocità", "Modulo del vettore nell'unità di velocità globale. Zero dipinge una calma definita, che è diversa da un'area vuota."];
const direction: Parameter[] = [
  ["Modalità direzione", "Costante usa un'unica direzione della bussola. Verso un punto punta a un obiettivo, calcolato separatamente in ogni posizione; Lontano da un punto inverte quella direzione. Vengono mostrate solo le opzioni pertinenti."],
  ["Direzione", "Gradi nella convenzione da / verso del progetto. Il nord è 0°, l'est 90°, il sud 180°, l'ovest 270°. Con il vento «da», 270° dipinge un vento che si muove verso est."],
  ["Obiettivo / Scegli sulla mappa", "Inserire la longitudine e poi la latitudine, oppure premere Scegli sulla mappa e fare clic sull'obiettivo. La longitudine positiva è est; la latitudine positiva è nord. Quel clic di scelta posiziona l'obiettivo invece di dipingere."],
  ["Direzione verso l'obiettivo: Ortodromia / Lossodromia", "Ortodromia usa la rotta locale del percorso sferico più breve. Lossodromia usa una rotta bussola costante verso l'obiettivo. Le due possono differire notevolmente su percorsi lunghi e alle alte latitudini."],
  ["Angolo rispetto all'obiettivo", "Sposta la direzione risultante da −180° a +180°. Zero punta direttamente verso l'obiettivo o in senso opposto. Gli angoli positivi ruotano in senso orario; quelli negativi in senso antiorario."],
];
const eyedropper: Parameter = ["Contagocce", "Fare clic su di esso e poi su un punto della mappa con dati definiti per copiare velocità e direzione nello strumento. Campiona i dati visibili del tipo di campo attivo. È disponibile nelle modalità a vettore singolo, non nei gradienti a due estremi."];
const modifier = "Un oggetto di modifica cambia i dati sottostanti nel proprio livello. Non può creare flusso su dati non definiti. Posizionarlo sopra gli oggetti su cui deve agire. La sua trasformazione, intensità, durata e le proprietà supportate possono essere animate.";

/** Guida di riferimento integrata offline. I valori nelle schermate sono esempi, non valori predefiniti. */
const topics: HelpTopic[] = [
  { id: "workspace", group: "Area di lavoro", title: "Per iniziare", paragraphs: [
    "VectorEffects crea campi animati di vento e di corrente superficiale a partire da oggetti dipinti, file GRIB, archivi storici e macro catturate. L'area di disegno contiene la mappa di base. I livelli vuoti sono trasparenti; solo i dati definiti e le sovrapposizioni di immagini coprono ciò che sta sotto.",
    "Questa guida di riferimento, consultabile con la ricerca, funziona offline. Scegliere una pagina a sinistra e fare clic sulle schermate per vederle a grandezza piena. Le schermate mostrano progetti di esempio di una beta precedente: i valori di sfumatura diversi da zero sono esempi, l'angolo di Cerchio ora usa un cursore e la vecchia opzione Assoluta di Curva ora si chiama Costante.",
  ], steps: ["Scegliere Nuovo… e impostare la risoluzione della griglia, il passo temporale e il numero di passi.", "Selezionare un livello sbloccato, scegliere Pennello, impostare velocità e direzione e trascinare sulla mappa.", "Selezionare il nuovo oggetto per esaminarlo o animarlo.", "Salvare come .veproj per conservare gli oggetti modificabili. Usare Esporta GRIB… per ottenere dati vettoriali da usare in un altro programma."],
    images: [shot("overview/overview", "La mappa, le opzioni dello strumento, i livelli, le proprietà, la cronologia e la linea temporale.")], related: ["projects", "tools", "layers", "animation", "export"] },
  { id: "projects", group: "Area di lavoro", title: "Progetti, salvataggio e ripristino", paragraphs: ["Usare il menu Progetto nella barra del titolo per Nuovo…, Apri…, Salva, Salva con nome… e Chiudi. Un progetto memorizza la griglia, la linea temporale, i livelli, la geometria e l'animazione. Mantenere i file di origine importati nei percorsi a cui fa riferimento quando si riapre o si sposta un progetto. Conservare il file .veproj come originale modificabile dopo l'esportazione."],
    parameters: [["Nuovo…: Nome", "Assegna un nome al progetto. Impostare il tipo di campo di ogni livello dipinto nel pannello dei livelli."], ["Risoluzione", "Spaziatura geografica della griglia. Una griglia più fine risolve dettagli più piccoli, ma aumenta il tempo di valutazione e la dimensione dell'esportazione."], ["Passo temporale / Passi", "Ore simulate tra un passo e l'altro e numero totale di passi. Sono diversi dai fotogrammi al secondo della riproduzione."], ["Apri… / Recenti", "Apre un file .veproj. Recenti elenca i file esistenti; usare Apri… per trovare un progetto spostato."], ["Salva / Salva con nome…", "Salva aggiorna il file corrente. Salva con nome… sceglie un nuovo percorso. Un progetto mai salvato richiede prima un percorso."], ["Chiudi", "Chiude il progetto. Se c'è lavoro non salvato, propone Salva, Non salvare o Annulla."], ["Salvataggio automatico", "Impostazioni permette di conservare istantanee di ripristino, salvare direttamente nel file del progetto o lasciare il salvataggio manuale. Scatta ogni minuto o ogni cinquanta modifiche, a seconda di quale evento si verifica prima. Dopo un arresto anomalo, la pagina iniziale propone di recuperare il lavoro."], ["Annulla / Ripeti / Cronologia", "Annullano o riapplicano le modifiche al documento; Cronologia le descrive. Un gesto completo è una sola modifica, quindi un Annulla rimuove un tratto o ripristina una regione cancellata."]],
    images: [shot("overview/project_management", "I controlli del progetto e l'ingranaggio delle Impostazioni.")], related: ["settings", "export", "troubleshooting"] },
  { id: "view", group: "Area di lavoro", title: "Vista della mappa e convenzioni di direzione", paragraphs: ["Spostare la vista con lo strumento Mano e fare zoom con la rotellina o il trackpad. Le impostazioni di visualizzazione influiscono sulla presentazione, non sui vettori esportati."],
    parameters: [["Cattura", "Entra nella modalità di cattura delle macro per registrare una regione lungo i fotogrammi."], ["Misura", "Apre i cerchi di distanza, il compasso a punte fisse, i confronti tra rotte e la velocità di spostamento. Le misurazioni non dipingono dati vettoriali."], ["Simboli", "Mostra o nasconde le direzioni: barbe meteorologiche per il vento e frecce per le correnti."], ["Proiezione", "Cercare tra 270 viste per nome, paese o codice EPSG: mappe cilindriche e mondiali, un globo ortografico, mappe azimutali, griglie polari nord/sud, griglie nazionali e tutte le zone UTM WGS84. Le mappe regionali si adattano alla loro area di utilizzo; trascinare un globo o una mappa azimutale ne cambia il centro. La proiezione personalizzata accetta PROJ, WKT o un codice EPSG incluso. Le definizioni funzionano offline; le griglie di correzione del datum geodetico non sono incluse. Questo cambia la vista, non i dati memorizzati né le esportazioni. Nelle viste curve, le dimensioni in pixel si convertono in geometria sul terreno nel punto di inizio del gesto."], ["Reticolo", "Mostra le linee di riferimento di longitudine e latitudine."], ["Scala automatica", "Adatta i massimi della scala di colori ai dati visibili. Disattivarla per confrontare con le scale fisse del progetto."], ["Legenda", "Mostra il gradiente, il tipo di campo, le unità di velocità e i limiti della scala."], ["Lettura", "Mostra le coordinate del puntatore, la velocità e la direzione campionate e lo zoom. «Nessun campo» significa dati non definiti."], ["Frecce e barbe del vento", "Una freccia punta dove va la corrente. Una barba del vento punta verso la direzione da cui proviene il vento, con le barbe a quell'estremità. La barba di un vento da nord punta a nord, ma il suo flusso procede verso sud. La convenzione numerica di direzione non inverte le barbe meteorologiche."]],
    images: [shot("overview/view_and_global_settings", "Cattura, misura, annulla/ripeti e controlli di visualizzazione della mappa.")], related: ["targets", "settings", "measure", "divergence"] },
  { id: "layers", group: "Area di lavoro", title: "Livelli, sovrapposizione e filtri di velocità", paragraphs: ["L'elenco mostra per prima la cima della pila. I livelli dipinti contengono oggetti e sono completamente trasparenti dove quegli oggetti non definiscono dati. La mappa di base sta sotto la pila e non ha una riga di livello. È possibile eliminare tutti i livelli; aggiungere un nuovo livello per riprendere a dipingere o usare Annulla per ripristinarne uno."],
    parameters: [["+ / Importa GRIB / Importa Zarr / + immagine / Calendario / Antenna", "Aggiungono un livello dipinto, importano vettori, aggiungono un'immagine di riferimento o scaricano dati storici. L'antenna scarica gli ultimi giorni di dati osservati."], ["Nome / triangolo di espansione", "Seleziona il livello o ne espande l'elenco degli oggetti."], ["Maniglia di trascinamento / frecce su e giù", "Riordinano i livelli trascinandone le intestazioni o con le frecce. Trascinare le righe degli oggetti per riordinarli, o su un altro livello per spostarli. Gli oggetti di modifica e di clonazione leggono ciò che sta sotto di loro in quel livello."], ["Occhio / lucchetto", "Nasconde un livello o impedisce di modificarne gli oggetti. Sbloccarlo prima di disegnare o trasformare."], ["Campo", "Seleziona il tipo per i livelli dipinti. I livelli importati indicano il tipo della loro origine. Vento e correnti restano campi separati."], ["Filtro di velocità: minima / massima", "Attiva un intervallo di velocità inclusivo nelle unità di visualizzazione. I valori al di fuori diventano trasparenti. Il filtro si applica dopo gli oggetti e le modifiche del livello; tutti i tipi di livello lo supportano. Le soglie delle immagini usano la velocità vettoriale nelle posizioni dell'immagine."], ["Duplica / ×", "Duplica un oggetto, elimina un oggetto o elimina un livello e i suoi oggetti. Annulla ripristina le eliminazioni dal documento."]],
    images: [shot("overview/layer_panel", "I controlli dei livelli e il filtro di velocità facoltativo.")], related: ["selection", "imports", "history", "clone"] },
  { id: "selection", group: "Area di lavoro", title: "Selezione, proprietà e trasformazioni", paragraphs: ["Selezionare dal pannello dei livelli o con lo strumento di selezione; Maiusc-clic estende la selezione. Solo gli oggetti selezionati compaiono nell'anteprima in movimento, anche se altri oggetti si sovrappongono ai loro limiti. Scegliere un livello o disegnare una regione può cambiare l'ambito della selezione."],
    parameters: [["Posizione / Scegli", "Longitudine e latitudine dell'ancoraggio. Scegli la assegna con un clic sulla mappa. Trascinare sposta l'ancoraggio; creare chiavi di Posizione lo fa viaggiare."], ["Scala", "Ridimensiona attorno all'ancoraggio. 100% è la dimensione originale. Cambia la geometria, non la velocità dei vettori."], ["Rotazione", "Ruota l'oggetto e il suo campo attorno all'ancoraggio. Lo strumento di modifica Ruota flusso, invece, gira i vettori senza spostare l'impronta del campo."], ["Visibile", "Attiva l'oggetto; creare chiavi per accenderlo e spegnerlo nel tempo."], ["Maniglie di trasformazione", "Spostano, ruotano o scalano la selezione al fotogramma corrente, secondo le regole dei fotogrammi chiave."], ["Rombi delle proprietà", "Aggiungono una chiave al fotogramma selezionato. La linea temporale mostra le stesse proprietà e le loro chiavi."], ["Dettagli del livello", "Senza oggetti selezionati, Proprietà descrive il livello attivo: origine, file o archivio, tipo di campo e copertura dei fotogrammi."], feather, edge],
    images: [shot("overview/properties_history", "Proprietà dell'oggetto, rombi di animazione e cronologia delle modifiche.")], related: ["animation", "shape", "tools"] },
  { id: "tools", group: "Strumenti di creazione", title: "Nozioni di base: dimensione, sfumatura e bordi", paragraphs: ["Le opzioni dello strumento definiscono i nuovi gesti; il pannello delle proprietà modifica gli oggetti esistenti. Dopo aver cambiato un'opzione, il clic successivo sulla mappa usa lo strumento. Scegli sulla mappa e il contagocce riservano di proposito un clic per scegliere o campionare.", "Un gesto completo diventa un oggetto; i tratti compatibili possono unirsi a seconda dello strumento attivo e delle impostazioni. Gli strumenti di creazione dipingono vettori, mentre gli strumenti di modifica cambiano i dati sottostanti. Vengono mostrate solo le opzioni che hanno senso nella modalità corrente."],
    parameters: [size, brushShape, feather, edge, eyedropper, ["Geometria in pixel", "px significa pixel al momento della creazione, anche alle alte latitudini. La geografia salvata resta ancorata quando si sposta la vista, si fa zoom o si cambia proiezione."], ["Scelte di geometria fisse", "Scelte come la forma dell'impronta originale sono fissate dopo la creazione. Usare l'animazione della forma per rimodellare l'oggetto invece di cambiarne la modalità di costruzione."]],
    images: [shot("overview/tool_bar", "Mano, Seleziona, Gomma, Inserisci macro, Pennello, Cerchio, Riempimento forma, Timbro clone, Curva, Maschera, Intensifica / riduci, Divergenza / convergenza, Ruota flusso, Deforma e Trasla.")], related: ["brush", "circle", "path", "eraser"] },
  { id: "brush", group: "Strumenti di creazione", title: "Pennello", paragraphs: ["Trascinare per dipingere un cerchio o un quadrato lungo il gesto; fare clic per una singola impronta. Usare un flusso costante oppure orientare ogni vettore verso un obiettivo o in senso opposto. Il bordo segue la Sfumatura e la modalità Bordo."],
    parameters: [brushShape, size, speed, ...direction, feather, edge, eyedropper],
    images: [shot("create_tools/brush_tool_constant", "Un pennello con direzione del vento costante. La sfumatura è un valore di esempio.")], related: ["targets", "tools", "animation"] },
  { id: "targets", group: "Strumenti di creazione", title: "Rotte verso un obiettivo e scostamenti angolari", paragraphs: ["Le modalità con obiettivo fanno variare la direzione all'interno di un oggetto. Compaiono in Pennello e nella modalità a vettore costante di Riempimento forma. Spostare o animare l'obiettivo cambia il punto di mira senza ridisegnare la forma."],
    parameters: direction,
    steps: ["Scegliere Verso un punto o Lontano da un punto.", "Inserire le coordinate o usare Scegli sulla mappa.", "Scegliere Ortodromia o Lossodromia.", "Lasciare Angolo rispetto all'obiettivo a 0 per puntare direttamente, o inserire uno scostamento.", "Dipingere e controllare diverse posizioni con la lettura; le barbe del vento mostrano la direzione di provenienza."],
    images: [shot("create_tools/brush_tool_point", "Coordinate dell'obiettivo, scelta della rotta e scostamento angolare.")], related: ["view", "brush", "fill", "measure"] },
  { id: "circle", group: "Strumenti di creazione", title: "Impronta Cerchio", paragraphs: ["Fare clic per posizionare un flusso circolare attorno al puntatore. Scegliere un disco, un anello o un disco con gradiente radiale di velocità. L'angolo inclina il flusso verso l'interno o verso l'esterno mantenendo la velocità scelta."],
    parameters: [["Riempimento: Pieno / Perimetro / Pieno con gradiente", "Pieno dipinge il disco alla Velocità indicata. Perimetro lascia il centro non definito. Pieno con gradiente fa variare la velocità dal centro al bordo."], ["Diametro / Larghezza dell'anello", "Diametro esterno e spessore della fascia perimetrale. Entrambi usano l'unità px o sul terreno selezionata."], speed, ["Velocità (centro) / Velocità (bordo)", "Velocità agli estremi per Pieno con gradiente. Un centro a zero è una calma definita, non un buco vuoto."], ["Rotazione: Orario / Antiorario", "Circolazione in senso orario o antiorario con angolo tangente pari a zero."], ["Angolo dalla tangente", "Cursore da −90° a +90°. −90° punta direttamente verso l'interno; 0° segue la tangente; +90° punta verso l'esterno. I valori intermedi producono un flusso a spirale. Il valore è in gradi."], feather, edge],
    images: [shot("create_tools/circle_tool", "I parametri di Cerchio. L'angolo dalla tangente ora usa un cursore da −90° a +90°.")], related: ["tools", "divergence", "shape"] },
  { id: "fill", group: "Strumenti di creazione", title: "Riempimento forma e gradienti vettoriali", paragraphs: ["Dipingere una forma predefinita trascinata o un poligono. Il contorno determina dove esistono i dati; la Modalità vettore determina i vettori all'interno. Un gradiente mescola i vettori agli estremi, quindi direzioni diverse agli estremi possono cambiare anche la velocità tra di essi."],
    parameters: [["Forma: Poligono / Quadrato / Rettangolo / Cerchio", "Fare clic sui vertici del poligono e terminare con Invio o doppio clic. Trascinare per tracciare una forma predefinita. Esc annulla una costruzione non terminata."], ["Forma in", "Le unità sul terreno definiscono una geometria geografica; px usa il piano dello schermo cilindrico corrente, oppure una dimensione locale sul terreno nelle viste a globo, azimutali e regionali."], ["Modalità vettore: Costante / Gradiente", "Costante usa una velocità e la modalità direzione. Gradiente distribuisce i vettori iniziale e finale sulla forma."], speed, ...direction, ["Velocità (inizio) / Velocità (fine)", "Moduli agli estremi opposti del gradiente."], ["Direzione (inizio) / Direzione (fine)", "Direzioni agli estremi nella convenzione da / verso del progetto."], ["Asse del gradiente", "Rilevamento geometrico dall'inizio del gradiente verso la sua fine. È un asse, non una direzione di provenienza del vento."], feather, edge],
    images: [shot("create_tools/shape_fill", "Un poligono con un gradiente vettoriale.")], related: ["targets", "shape", "selection"] },
  { id: "clone", group: "Strumenti di creazione", title: "Timbro clone e trasparenza", paragraphs: ["Il timbro clone copia i vettori che si trovano sotto di esso nello stesso livello, non la mappa di base né i colori di sfondo. I vuoti dell'origine restano trasparenti durante l'anteprima e dopo il rilascio. Un'origine a velocità zero realmente definita viene comunque copiata come calma.", "Gli oggetti di origine vengono valutati al fotogramma corrente, quindi le loro modifiche e la loro animazione possono cambiare il clone. Gli oggetti sopra il clone non ne diventano l'origine."],
    parameters: [brushShape, size, ["Origine / Scegli sulla mappa", "Coordinate dell'ancoraggio di origine. Sceglierle prima di dipingere la destinazione."], ["Scostamento: Allineato", "Mantiene lo scostamento tra l'ancoraggio di destinazione e l'origine. Man mano che la posizione di campionamento si sposta, la sua origine si sposta della stessa quantità."], ["Scostamento: Fisso", "Ricomincia il campionamento attorno all'origine scelta a ogni impronta lungo il tratto, applicando ripetutamente quella zona di origine."], feather, edge],
    steps: ["Attivare il livello che contiene gli oggetti di origine.", "Scegliere Timbro clone e scegliere un'origine con dati definiti.", "Impostare dimensione, modalità di scostamento e sfumatura.", "Dipingere la destinazione. Le celle di origine non definite la lasciano invariata."],
    images: [shot("create_tools/clone_stamp", "I controlli Origine e Scostamento su un campo clonato.")], related: ["layers", "tools", "troubleshooting"] },
  { id: "path", group: "Strumenti di creazione", title: "Strumento Curva", paragraphs: ["Dipingere un corridoio per una corrente a getto, un fronte o un canale. Posizionare i punti del percorso e terminare con Invio o doppio clic. Esc abbandona un tracciato non terminato. Il flusso può seguire il percorso o restare costante."],
    parameters: [["Curva: Polilinea / Bézier", "Polilinea unisce i vertici con segmenti rettilinei. Bézier offre segmenti curvi e maniglie di controllo."], ["Larghezza", "Larghezza totale del corridoio in px o in unità sul terreno."], speed, ["Modalità direzione: Costante", "Un'unica direzione della bussola in tutto il corridoio. Le versioni precedenti la chiamavano Assoluta; il comportamento non è cambiato."], ["Modalità direzione: Relativa al tracciato", "Usa la tangente locale. Una direzione di 0° segue l'ordine dei punti, 180° scorre all'indietro lungo di esso e 90° lo attraversa."], ["Direzione", "Una rotta bussola nella modalità Costante, secondo la convenzione del progetto; uno scostamento geometrico dalla tangente nella modalità Relativa al tracciato. Gli scostamenti non vengono convertiti in direzioni di provenienza del vento."], feather, edge, eyedropper],
    images: [shot("create_tools/path_tool", "Un corridoio i cui vettori seguono il percorso.")], related: ["tools", "shape", "animation"] },
  { id: "mask", group: "Strumenti di modifica", title: "Maschera", paragraphs: ["Una maschera rimuove la copertura dei dati precedenti nel suo livello, lasciando vedere i livelli sottostanti. Resta un oggetto modificabile e animabile. La cancellazione, invece, rimuove la geometria in modo distruttivo."],
    parameters: [brushShape, size, feather, ["Inverti", "Disattivato, maschera l'interno dell'impronta. Attivato, maschera l'esterno, limitando i dati precedenti del livello a quella regione."], edge],
    images: [shot("edit_tools/mask_tool", "Una maschera che attraversa forme dipinte.")], related: ["eraser", "layers", "shape"] },
  { id: "intensity", group: "Strumenti di modifica", title: "Intensifica / riduci", paragraphs: [modifier, "Cambia la velocità mantenendo la direzione. Un vettore nullo resta in calma."],
    parameters: [size, ["Intensità", "Cursore da −100% a +200%. Zero non fa nulla; +100% raddoppia la velocità; +200% la triplica; −50% la dimezza; −100% produce una calma definita. La sfumatura fonde verso la velocità originale sul bordo."], feather],
    images: [shot("edit_tools/intensify_tool", "Aumento della velocità sotto l'impronta di un modificatore.")], related: ["divergence", "rotation", "layers"] },
  { id: "divergence", group: "Strumenti di modifica", title: "Divergenza / convergenza", paragraphs: [modifier, "La divergenza piega il flusso allontanandolo dal centro dell'impronta o dall'asse del tratto; la convergenza lo piega verso di esso. La velocità viene conservata. Le barbe del vento puntano verso il vento in arrivo: le loro aste possono puntare verso l'interno quando il flusso reale diverge.", "Per un flusso verso nord a est del centro di un'impronta, la divergenza aggiunge una componente verso est; la convergenza aggiunge una componente verso ovest."],
    parameters: [size, ["Intensità: Divergenza (verso l'esterno)", "Il lato sinistro piega il flusso verso l'esterno. Un'intensità maggiore aggiunge una componente radiale più forte prima di ripristinare la velocità originale."], ["Intensità: Convergenza (verso l'interno)", "Il lato destro piega il flusso verso l'interno. Il centro è neutro. La percentuale è la forza dell'effetto, non una variazione di velocità."], feather],
    images: [shot("edit_tools/convergence_divergence_tool", "Divergenza su dati di vento; le barbe indicano la direzione di provenienza.")], related: ["view", "circle", "rotation"] },
  { id: "rotation", group: "Strumenti di modifica", title: "Strumento di modifica Ruota flusso", paragraphs: [modifier, "Ruota i vettori sul posto, mantenendo la loro impronta e le strutture spaziali dove si trovavano."],
    parameters: [size, ["Senso di rotazione: Orario / Antiorario", "In che senso ruotare il flusso sottostante."], ["Intensità", "Da 0° a 180°. Zero è neutro, 90° gira il flusso di lato e 180° ne inverte la direzione. La velocità viene conservata."], feather],
    images: [shot("edit_tools/rotation_tool", "Rotazione di 30° dei vettori sottostanti.")], related: ["selection", "warp", "intensity"] },
  { id: "warp", group: "Strumenti di modifica", title: "Deforma e trasla", paragraphs: [modifier, "Deforma sposta le posizioni di campionamento in modo da spingere o torcere le strutture del campo. Trasla è uno strumento in due tempi: dipingere per selezionare un'area, rilasciare, poi trascinare la selezione nella nuova posizione. Con la Sfumatura a zero il campo selezionato si sposta intatto; la Sfumatura ne ammorbidisce il bordo interno conservandone il nucleo. Entrambi i contorni restano evidenziati, con una linea che ne unisce i centri. L'area lasciata libera e una fascia attorno alla destinazione vengono interpolate per adattarsi al campo circostante. Esc annulla la selezione in sospeso."],
    parameters: [size, ["Deforma: Spinta", "Sposta il campo verso Spingi verso. Trascinare con Maiusc imposta la trazione dall'ancoraggio alla sua destinazione."], ["Spingi verso", "Coordinate di destinazione comuni a tutti i fotogrammi. Spingi verso non ammette chiavi; Posizione può comunque animare la collocazione dell'oggetto."], ["Deforma: Torsione", "Torce il campionamento attorno all'ancoraggio."], ["Torsione", "Angolo con segno da −360° a +360°. Zero è neutro; il segno cambia il senso di rotazione."], ["Trasla: Distanza di interpolazione", "Fin dove si estende l'interpolazione oltre il contorno di destinazione, nell'unità di distanza px o geografica del pennello. Con zero, l'area di origine lasciata libera viene comunque riempita."], ["Animazione di Trasla", "Posizione della selezione, Posizione della traslazione (relativa), Sfumatura e Distanza di interpolazione hanno tracce indipendenti. Posizione della traslazione ha coordinate accoppiate con chiavi e andamento condivisi. Trascinare con Maiusc la selezione di origine per creare una chiave della sua destinazione relativa con Chiave automatica. Trasla non ha animazione della forma."], feather],
    images: [shot("edit_tools/warp_tool", "Modalità Torsione con dimensione, angolo e sfumatura.")], related: ["rotation", "selection", "shape"] },
  { id: "eraser", group: "Strumenti di modifica", title: "Gomma e tagli distruttivi", paragraphs: ["La gomma rimuove geometria dagli oggetti o dai dati del livello attivo. Non dipinge sfondo né valori a velocità zero. Annulla ripristina il taglio; usare una maschera per ottenere un ritaglio separato e rimovibile.", "I tagli restano anche quando cambiano i perimetri animati. Selezionare Gomma esce dalla modifica della forma e nasconde i punti del perimetro."],
    parameters: [brushShape, size, feather], steps: ["Attivare e sbloccare il livello desiderato.", "Scegliere Cerchio o Quadrato e una dimensione in px o sul terreno.", "Usare Sfumatura 0 per un taglio netto o aumentarla per ammorbidirlo.", "Trascinare sulla regione indesiderata. Annulla la ripristina."],
    images: [shot("utility_tools/eraser", "Una gomma da 400 pixel in Mercator.")], related: ["mask", "shape", "layers"] },
  { id: "animation", group: "Animazione", title: "Fotogrammi chiave e movimento", paragraphs: ["La testina di riproduzione sceglie il fotogramma da modificare. Espandere un oggetto per vederne le proprietà animabili. I rombi sono chiavi; tra di esse i valori seguono la loro interpolazione. Andare a un fotogramma, aggiungere un rombo e modificare le proprietà o le maniglie sulla mappa.", "Chiave automatica può creare chiavi durante la modifica. Le modalità di direzione, il Riempimento di Cerchio, lo Scostamento di Timbro clone, Inverti di Maschera e la modalità/Spingi verso di Deforma valgono per l'intero oggetto e non ammettono chiavi. Quando una proprietà ha già delle chiavi, modificarla a un altro fotogramma aggiunge una chiave invece di cambiare l'intera animazione."],
    parameters: [["Riproduci / Pausa / Ferma", "Riproduci avanza dal fotogramma corrente; Pausa lo mantiene; Ferma torna all'inizio."], ["Ciclo", "Ripete la riproduzione dopo l'ultimo fotogramma."], ["passi/s", "Fotogrammi al secondo di visualizzazione richiesti, distinti dalle ore simulate per fotogramma. I dati importati non ancora preparati possono richiedere tempo per caricarsi."], ["Chiave automatica", "Controlla la creazione automatica di chiavi quando si modificano proprietà animabili."], ["Passi", "Numero totale di fotogrammi. Accorciare la linea temporale può rimuovere chiavi successive e richiede una conferma."], ["Tempo / Aggiungi ora di inizio / ×", "Imposta o rimuove l'ora di inizio UTC. Senza di essa il righello mostra ore relative; con essa sono disponibili date UTC assolute."], ["Barra di preparazione", "Mostra i fotogrammi preparati. I grandi insiemi di dati importati richiedono tempo per la preparazione iniziale."], ["Grafico dei valori / andamento", "Espandere una proprietà per esaminarne i valori nel tempo. Fare clic destro su una chiave per scegliere l'interpolazione disponibile per il tratto che parte da essa."], ["Selezione delle chiavi", "Fare clic sulle chiavi per selezionarle, trascinarle per spostarle e premere Canc per rimuoverle. Le chiavi selezionate hanno la precedenza sull'eliminazione degli oggetti."]],
    images: [shot("overview/timeline", "Trasporto, velocità di riproduzione, chiave automatica, ora e barre della durata."), shot("timeline/keyframes", "Chiavi delle proprietà e punti dei fotogrammi intermedi.")],
    sections: [{ heading: "Muoversi a velocità costante", paragraphs: ["Fare clic su →+ in Posizione. Il moto inizia al fotogramma selezionato e termina alla chiave di posizione successiva, o all'ultimo fotogramma dell'oggetto se non esiste una chiave successiva."], parameters: [["Direzione verso (° veri)", "Direzione di spostamento: 0° nord, 90° est, 180° sud, 270° ovest. Sempre «verso», indipendentemente dalla visualizzazione del vento come «da»."], ["Velocità", "Velocità di spostamento nell'unità di velocità globale."], ["Aggiungi moto / Annulla", "Crea il tracciato per l'intervallo indicato o annulla. Le chiavi esistenti nell'intervallo richiedono una conferma prima di essere sostituite. Un Annulla ripristina la traccia precedente."]], images: [shot("timeline/position_constant_motion", "Il controllo →+ in Posizione."), shot("timeline/position_constant_motion_dialog", "Direzione e velocità di spostamento per l'intervallo indicato.")] }],
    related: ["spans", "shape", "links", "motion-vectors"] },
  { id: "spans", group: "Animazione", title: "Durata dell'oggetto: fotogrammi iniziale e finale", paragraphs: ["La barra della durata fissa i fotogrammi, estremi inclusi, in cui un oggetto contribuisce. È separata dalle chiavi di animazione: un oggetto può avere una lunga traccia di movimento ma essere attivo solo per una parte di essa."],
    parameters: [["Maniglia di inizio", "Trascinare l'appiglio sinistro per impostare il primo fotogramma attivo. La sua area cliccabile si estende oltre la sottile barra dipinta."], ["Maniglia di fine", "Trascinare l'appiglio destro per impostare l'ultimo fotogramma attivo."], ["Corpo della barra", "Trascinarlo per spostare l'intero intervallo mantenendone la lunghezza. Un clic senza movimento seleziona l'oggetto."], ["Anteprima al rilascio", "La barra mantiene la posizione di rilascio mentre le righe del documento si aggiornano, senza tornare di scatto all'intervallo precedente."]],
    images: [shot("timeline/keyframes", "La barra della durata sta sopra le tracce delle singole proprietà.")], related: ["animation", "macros", "shape"] },
  { id: "shape", group: "Animazione", title: "Animare la forma di un oggetto", paragraphs: ["L'animazione della forma è una modalità di modifica per gli oggetti di creazione e di modifica, escluse le macro catturate, le toppe e le selezioni di Trasla. I punti del perimetro conservano la loro identità tra le chiavi e compaiono solo mentre il pulsante della forma dell'oggetto è attivo."],
    steps: ["Selezionare l'oggetto e fare clic sull'icona del perimetro accanto al suo nome nella linea temporale.", "Al fotogramma desiderato, trascinare i punti e aggiungere una chiave di Forma con il suo rombo, se necessario.", "Andare a un altro fotogramma e spostare di nuovo i punti.", "Scorrere la linea temporale per esaminare il contorno che cambia.", "Fare di nuovo clic sull'icona del perimetro o scegliere un altro strumento per uscire dalla modalità e nascondere i punti."],
    parameters: [["Punti del perimetro", "Posizioni lungo il contorno al fotogramma corrente. Appartengono all'animazione dell'oggetto, non sono oggetti separati."], ["Traccia Forma / rombo", "Memorizza un contorno a un fotogramma. Altre chiavi definiscono i contorni tra cui interpolare."], ["Interazione con la gomma", "I tagli restano distruttivi e non vengono ripristinati solo perché il contorno cambia in seguito."]],
    images: [shot("timeline/shape_keyframes", "Punti del perimetro e una traccia Forma con chiavi.")], related: ["animation", "eraser", "selection"] },
  { id: "links", group: "Animazione", title: "Collegare posizione o rotazione", paragraphs: ["Un collegamento di inseguimento fa seguire a una proprietà la proprietà corrispondente di un oggetto principale, così che le strutture si muovano o ruotino insieme."],
    steps: ["Espandere entrambi gli oggetti.", "Fare clic sul controllo di collegamento di Posizione o Rotazione dell'oggetto che segue.", "Fare clic sulla riga di quella proprietà dell'oggetto principale. Un nuovo clic sul controllo armato annulla.", "Modificare la traccia dell'oggetto principale. Fare clic sul collegamento attivo per scollegare prima di creare una traccia indipendente."],
    parameters: [["Controllo di collegamento", "Arma, segnala o rimuove un collegamento di inseguimento. È possibile anche trascinare tra le righe corrispondenti."], ["Rombi seguiti", "Rappresentano l'animazione dell'oggetto principale. Modificarli sulla riga dell'oggetto principale invece di trattarli come chiavi indipendenti dell'oggetto che segue."]],
    images: [shot("timeline/link_motion_to_object", "Una riga Posizione seguita, con il suggerimento per scollegare.")], related: ["animation", "motion-vectors"] },
  { id: "motion-vectors", group: "Animazione", title: "Aggiungere il movimento dell'oggetto ai suoi vettori", paragraphs: ["Spostare una forma e cambiarne i vettori dipinti sono scelte separate. Il contributo del moto aggiunge il movimento dell'oggetto al campo. Non crea un tracciato: prima animare le trasformazioni, poi attivarne i contributi.", "I vettori di moto si combinano con i vettori originali, quindi possono cambiare sia la velocità sia la direzione."],
    parameters: [["Contributo del moto (⇢)", "Aggiunge il movimento associato a quella trasformazione. Posizione contribuisce con la velocità di spostamento; i contributi disponibili di Scala e Rotazione tengono conto delle loro trasformazioni variabili."], ["Moto costante (→+)", "Crea un tracciato di Posizione. È diverso dall'aggiungere movimento ai vettori dipinti."], ["Trasformazione statica", "Una trasformazione che non cambia non contribuisce alcun movimento, anche con il controllo attivo."]],
    images: [shot("timeline/add_motion_vectors", "Contributo del moto attivato su una traccia Posizione con chiavi.")], related: ["animation", "links", "macros"] },
  { id: "imports", group: "Dati e macro", title: "GRIB, Zarr e immagini di riferimento", paragraphs: ["Le importazioni GRIB e Zarr di routing aggiungono i campi di vento e di corrente supportati come livelli separati. Ogni fotogramma usa l'ora di origine assegnata a quel passo del progetto. Le immagini sono riferimenti visivi e non contengono dati vettoriali esportabili."],
    parameters: [["Importa GRIB", "Scegliere il file; esaminarne campo, fotogrammi, percorso e copertura in Dettagli del livello. Mantenerlo disponibile per riaprire il progetto."], ["Importa Zarr / Apri da Zarr…", "Scegliere la cartella Zarr di routing (con o senza il suffisso .zarr). Vento e correnti diventano normali livelli modificabili. Apri da Zarr…, nella pagina iniziale, prende inoltre la griglia e l'orologio del progetto dall'archivio, entro il limite di 240 fotogrammi della linea temporale. Mantenere disponibile la cartella originale per riaprire il progetto."], ["Celle dei fotogrammi importati", "Selezionare i fotogrammi nella riga del livello di origine nella linea temporale. Copia, incolla ed elimina agiscono su quei fotogrammi invece che sulle chiavi degli oggetti. Maiusc estende una serie."], ["+ immagine", "Scegliere un'immagine di riferimento e la sua collocazione geografica."], ["Dimensione e forma dell'immagine", "Selezionare il livello immagine e usare lo strumento Mano. Trascinare un angolo per ridimensionare in proporzione, o una maniglia laterale per allungare la larghezza o l'altezza. L'angolo o il lato opposto resta fisso. Trascinare all'interno dell'immagine per spostarla. Annulla annulla l'intero trascinamento."], ["Opacità dell'immagine", "Controlla quanto l'immagine copre l'area di disegno."], ["Filtro di velocità", "Limita la copertura del campo a un intervallo accettato; i filtri delle immagini usano la velocità nelle posizioni dell'immagine."], ["File mancante", "Ripristinare il percorso a cui si fa riferimento o importarlo di nuovo. I dati mancanti non vengono trattati come calma reale."], ["Livello disallineato", "Su una linea temporale con ora d'inizio, un livello da file il cui primo campo non è all'ora del passo su cui cade viene evidenziato nella linea temporale, con lo scarto nel suggerimento. Nulla viene bloccato e l'esportazione non cambia. Il pulsante accanto al nome sposta i campi sui passi alle cui ore sono validi; i passi nascosti, incollati e cancellati si spostano con loro. Un annullamento ripristina tutto."]], related: ["history", "layers", "export"] },
  { id: "history", group: "Dati e macro", title: "Scaricare vento e correnti storici", paragraphs: ["Il calendario del pannello dei livelli apre l'importazione storica. Scegliere le date UTC e gli archivi; ognuno diventa un livello. I download nella cache possono essere riutilizzati quando si torna a una richiesta o la si riprova."],
    parameters: [["Inizio (UTC) / Fine (UTC)", "Estremi inclusi, in ore intere. Intervalli più lunghi significano più fotogrammi e più download; controllare il riepilogo del carico di lavoro."], ["Imposta l'inizio della linea temporale", "Allinea l'inizio del progetto alla prima ora UTC richiesta."], ["Vento ERA5", "Seleziona l'archivio di vento a 10 m offerto."], ["GlobCurrent", "Seleziona l'archivio di corrente superficiale totale offerto."], ["Importa / Annulla", "Avvia la richiesta selezionata o lascia il progetto invariato prima di iniziare."], ["Avanzamento", "Il pannello inferiore segnala il download e la preparazione. Entrambi gli archivi o intervalli più lunghi aumentano il lavoro."], ["Riprova il download", "Compare accanto a un errore nel pannello inferiore e ripete la richiesta salvata, riutilizzando i dati nella cache. Navigare sulla mappa non lo chiude."]],
    images: [shot("layers/import_history", "Date UTC, scelta degli archivi, allineamento e riepilogo del carico di lavoro.")], related: ["imports", "nrt", "animation", "capture", "troubleshooting"] },
  { id: "nrt", group: "Dati e macro", title: "Scaricare vento e correnti in tempo quasi reale", paragraphs: ["Il pulsante con l'antenna, accanto al calendario del pannello dei livelli, scarica gli ultimi giorni di dati osservati, fino ad ora, per i prodotti selezionati e aggiunge un livello per ciascuno. I dati scaricati vengono scritti su disco, così il progetto si apre poi offline. Si accede alla rete solo premendo Importa.", "I prodotti sono in ritardo di circa un giorno rispetto al presente, quindi i passi più recenti sono di solito vuoti. Un prodotto giornaliero, come DUACS, viene mostrato in ogni passo del suo giorno. Un prodotto che non può essere scaricato viene indicato nella barra di stato, e gli altri arrivano comunque. I livelli si comportano come i livelli GRIB importati: valgono il filtro di velocità, la gomma e l'esportazione. I livelli di temperatura superficiale del mare fanno eccezione: sono disegnati sotto il campo e letti sotto il puntatore, e non vengono mai filtrati, cancellati né esportati."],
    parameters: [["Giorni", "Quanti giorni prima di oggi (UTC) inizia il periodo, alle 00:00; termina sempre ora. Il numero massimo offerto è quello che una linea temporale di 240 passi può contenere con il passo del progetto."], ["Imposta / Sposta l'inizio della linea temporale", "Assegna al primo passo del progetto l'inizio del periodo, così le date della linea temporale corrispondono ai dati. Indica Sposta quando il progetto ha già un'ora di inizio."], ["Allunga la linea temporale", "Offerto quando il periodo richiede più passi di quanti ne ha il progetto. Aggiunge passi affinché la linea temporale arrivi al presente; non viene mai accorciata. Senza spunta, vengono scaricati solo gli orari che i passi esistenti possono mostrare."], ["Copernicus MULTIOBS", "Corrente superficiale totale — geostrofica, indotta dal vento e di marea — oraria, a 0,25°."], ["Copernicus DUACS", "Corrente superficiale geostrofica da altimetria satellitare, giornaliera; mostrata in ogni passo del suo giorno."], ["Vento L4 Copernicus", "Vento a 10 m che combina satelliti e modello, orario."], ["ASCAT Metop-B/C", "Vento a 10 m da scatterometro dai due satelliti Metop, un livello al giorno con i passaggi della giornata uniti; nessun valore dove nessun satellite è passato."], ["CCMP NRT", "Vento a 10 m CCMP (Cross-Calibrated Multi-Platform), versione 2.1 in tempo quasi reale, ogni 6 ore a 0,25°, di Remote Sensing Systems, letto dal server OceanWatch della NOAA. Copre da 78° S a 78° N; più vicino ai poli non viene mostrato nulla."], ["NOAA Blended Seawinds", "La combinazione NOAA del vento a 10 m da tutti gli scatterometri e i radiometri in orbita, ogni sei ore a 0,25°, da NOAA CoastWatch. Ogni giorno è un file con i suoi quattro orari, scaricato una sola volta."], ["NOAA OISST", "Temperatura superficiale del mare a interpolazione ottimale della NOAA, versione 2.1: giornaliera a 0,25°, da satelliti, navi e boe, distribuita da NOAA NCEI. Aggiunge un livello di temperatura superficiale del mare."], ["NOAA Geo-Polar Blended", "Combinazione della NOAA della temperatura superficiale del mare da satelliti geostazionari e in orbita polare, giornaliera, letta a 0,25° da NOAA CoastWatch. Aggiunge un livello di temperatura superficiale del mare."], ["OSTIA (Met Office)", "Analisi operativa della temperatura superficiale del mare e del ghiaccio (OSTIA) del Met Office, giornaliera, letta a 0,2° dal Copernicus Marine Service. Aggiunge un livello di temperatura superficiale del mare."], ["CMC", "L’analisi giornaliera della temperatura superficiale del mare del Canadian Meteorological Centre, letta a 0,25° dalla sua griglia di 0,1°, dall’archivio PO.DAAC della NASA. Aggiunge un livello di temperatura superficiale del mare. Richiede un token NASA Earthdata, impostato nelle Impostazioni; senza, appare in grigio."], ["Token NASA Earthdata", "Si imposta in Impostazioni → NASA Earthdata. È conservato in un file a sé, inviato solo all’archivio PO.DAAC della NASA quando si scarica CMC, e non viene mai più mostrato né dato a un client di IA."], ["Livello di temperatura superficiale del mare", "Disegnato sotto il campo a colori, da −2 °C a 32 °C, con una propria legenda e la temperatura sotto il puntatore nella lettura. Solo visualizzazione: non vi si dipinge mai sopra e non viene mai esportato. L’unità si imposta in Impostazioni."], ["Costo", "Il numero di download e la dimensione approssimativa su disco, mostrati prima dell'importazione."]], related: ["history", "imports", "animation"] },
  { id: "capture", group: "Dati e macro", title: "Registrare e visualizzare in anteprima una macro", paragraphs: ["La cattura registra i dati vettoriali di una regione lungo i fotogrammi, includendo facoltativamente il suo movimento. Usa il tipo di campo attivo; i colori della mappa di base e le immagini non sono dati vettoriali."],
    steps: ["Scegliere il campo di origine e il primo fotogramma.", "Entrare nella modalità di cattura, scegliere una forma e disegnare la regione.", "Attivare Registra movimento se necessario, poi Avvia cattura.", "Andare ai fotogrammi successivi e spostare la regione per seguire la struttura.", "Terminare la registrazione per visualizzare in anteprima l'intervallo di fotogrammi.", "Usare Modifica macro per rivederla, Salva macro per darle un nome e conservarla, o Annulla per abbandonarla."],
    parameters: [["Forma", "Contorno della regione che delimita i dati catturati."], ["Registra movimento", "Conserva il movimento della regione di cattura lungo i fotogrammi visitati."], ["Chiavi di registrazione", "Posizioni della regione nei passi visitati. Scorrere la linea temporale per esaminare il tracciato tra di esse."], ["Anteprima", "Riproduce i dati catturati isolatamente. Fare clic sulla mappa per visualizzare in anteprima la collocazione altrove."], ["Modifica macro / Salva macro / Annulla", "Rivedono, salvano nella libreria o abbandonano la cattura. Le altre modifiche al documento sono disattivate durante la registrazione o l'anteprima."]],
    images: [shot("creating_macros/create_macro_select_frame_and_area", "Scegliere il primo fotogramma e la regione."), shot("creating_macros/record_macro_end", "Spostare la regione in un fotogramma successivo."), shot("creating_macros/record_macro_preview", "Anteprima prima del salvataggio.")], related: ["macros", "animation", "history"] },
  { id: "macros", group: "Dati e macro", title: "Inserire macro e interpolare i fotogrammi mancanti", paragraphs: ["Scegliere Inserisci macro, selezionare una voce della libreria e fare clic per posizionarla al fotogramma corrente. Il contorno che segue il puntatore mostra in anteprima la collocazione solo nel livello dipinto selezionato. Un cursore barrato significa che la macro non ha dati corrispondenti al tipo vento/corrente di quel livello, o che il livello non può accettarla; nessun oggetto viene posizionato in un altro livello. Una macro con entrambi i campi usa il campo corrispondente al livello selezionato. Diventa un oggetto con trasformazioni e durata modificabili.", "La strategia di interpolazione compare quando i fotogrammi registrati sono più distanziati di quelli del progetto, come una macro trioraria in un progetto orario. Questa strategia vale per l'intera macro e non può essere animata."],
    parameters: [["Selettore delle macro / Aggiorna", "Selezionare una voce della libreria per nome, durata, numero di fotogrammi e indicatore di movimento. Aggiorna ricarica il contenuto della libreria."], ["Ripeti fotogrammi", "Predefinito: mantiene l'ultimo fotogramma registrato fino al successivo."], ["Fotogrammi vuoti", "Non mostra dati della macro nei fotogrammi intermedi, lasciando vedere ciò che sta sotto."], ["Interpola", "Fonde u e v separatamente e interpola il movimento registrato. L'interpolazione per componenti evita che una direzione compia un giro completo al passaggio per il salto di rotta."], ["Ciclo", "Ripete la sequenza registrata all'interno della durata attiva dell'oggetto."], feather, edge, ["Cartella della libreria", "Si configura in Impostazioni. I progetti in cui sono state inserite conservano i propri fotogrammi di macro, quindi eliminare la libreria non rimuove le macro già presenti in un progetto."]],
    images: [shot("creating_macros/insert_macro_hover", "Il contorno di inserimento segue il puntatore."), shot("creating_macros/insert_macro_clicked", "Una macro inserita e la sua barra della durata.")], related: ["capture", "spans", "motion-vectors", "settings"] },
  { id: "measure", group: "Misurazioni", title: "Confronto tra ortodromia e lossodromia", paragraphs: ["Scegliere Ortodromia / lossodromia in Misura e fare clic su due estremi. L'ortodromia, o cerchio massimo, è il percorso sferico più breve, con una rotta locale che cambia. Una lossodromia mantiene una rotta costante ed è generalmente più lunga."],
    parameters: [["Etichetta GC", "Distanza e rotta iniziale del percorso ortodromico."], ["Etichetta RL", "Distanza e rotta costante della lossodromia."], ["Estremi", "Trascinarli per rivedere il confronto."], ["Alt-clic su un punto", "Rimuove quella misurazione."], ["Cancella ortodromia / lossodromia", "Rimuove tutti i confronti tra rotte, conservando le altre misurazioni."], ["Cancella tutto", "Rimuove tutte le annotazioni di misura, non gli oggetti vettoriali."]],
    images: [shot("global_utility_tools/great_circle_rhumb_line", "Curva ortodromica e lossodromia tratteggiata tra gli stessi estremi.")], related: ["targets", "rings", "dividers"] },
  { id: "rings", group: "Misurazioni", title: "Cerchi di distanza", paragraphs: ["Scegliere Cerchi di distanza e fare clic su un centro. I cerchi rappresentano distanze sul terreno, quindi una proiezione può deformarne l'aspetto."],
    parameters: [["Intervallo", "Distanza sul terreno tra i cerchi nell'unità di distanza globale."], ["Cerchi", "Numero di cerchi. Il raggio esterno è pari a Intervallo × Cerchi."], ["Modifica dell'ultimo gruppo", "Le modifiche aggiornano il gruppo attivo. Fare clic altrove per aggiungere un gruppo; trascinare una maniglia centrale per spostarlo."], ["Alt-clic su un punto", "Rimuove quel gruppo di cerchi."], ["Cancella cerchi di distanza / Cancella tutto", "Cancella i gruppi di cerchi o tutti i tipi di misurazione."]],
    images: [shot("global_utility_tools/range_rings", "Venti cerchi a intervalli di 50 nm, con un raggio esterno di 1000 nm.")], related: ["measure", "dividers", "settings"] },
  { id: "dividers", group: "Misurazioni", title: "Compasso a punte fisse e distanze su più tratti", paragraphs: ["Scegliere Compasso a punte fisse e fare clic sui waypoint successivi. Ogni tratto mostra distanza e rotta; la catena riporta la distanza cumulativa. Le misurazioni non alterano i vettori esportati."],
    parameters: [["Clic", "Aggiunge un tratto dall'ultimo waypoint."], ["Invio / Esc", "Termina la catena corrente."], ["Maniglie dei waypoint", "Trascinarle per rivedere la rotta e ricalcolare le distanze."], ["Alt-clic su un punto", "Rimuove quella misurazione."], ["Cancella compasso a punte fisse / Cancella tutto", "Cancella le catene o tutte le annotazioni di misura."]],
    images: [shot("global_utility_tools/dividers", "Una catena di più tratti con rotte e distanze totali.")], related: ["measure", "rings"] },
  { id: "feature-speed", group: "Misurazioni", title: "Velocità e direzione di un sistema in movimento", paragraphs: ["Scegliere Velocità di spostamento in Misura per sapere quanto velocemente e in quale direzione si sposta una depressione, un fronte o un vortice. Fare clic sul sistema, portare la linea temporale a un passo temporale successivo e fare di nuovo clic su di esso. La linea tra i due segni riporta la velocità media nell'unità di velocità globale e la rotta seguita dal sistema; la distanza e il tempo trascorso sono scritti accanto al secondo segno.", "Tra i due clic la linea temporale può solo avanzare: i passi precedenti sono attenuati, e lo scorrimento del righello, i tasti di passo e la riproduzione si fermano al passo del primo segno. La direzione è una rotta — verso dove si dirige il sistema — qualunque convenzione di direzione il progetto usi per il vento. Le misurazioni non alterano i vettori esportati."],
    parameters: [["Primo clic", "Segna dove si trova il sistema nel passo temporale corrente e impedisce alla linea temporale di tornare indietro."], ["Secondo clic", "In un passo temporale successivo, segna dove si è spostato il sistema e completa la misurazione."], ["Esc / Annulla", "Elimina il primo segno e libera la linea temporale."], ["Etichette", "Velocità media e rotta lungo la linea; distanza e ore trascorse accanto al secondo segno."], ["Maniglie dei segni", "Trascinare uno dei segni per rivedere la misurazione. I passi temporali restano quelli dei clic."], ["Alt-clic su un punto", "Rimuove quella misurazione."], ["Cancella velocità di spostamento / Cancella tutto", "Cancella queste misurazioni o tutte le annotazioni di misura."]], related: ["dividers", "measure", "animation"] },
  { id: "settings", group: "Impostazioni ed esportazione", title: "Temi, unità, frecce e barbe del vento", paragraphs: ["Aprire Impostazioni con l'ingranaggio o con il pulsante Impostazioni della pagina iniziale. La sezione Aspetto offre Originale (Mezzanotte), Salvia e verde acqua, Oceano, Prugna, Brace e Carta, oltre a un tema personalizzato. I temi si applicano subito in tutta l'applicazione e persistono indipendentemente dai progetti. Unità e stili dei simboli sono preferenze dell'applicazione; le scale di colori e i gradienti del progetto sono salvati nel progetto. Le scelte di presentazione non cambiano i moduli né le direzioni esportati."],
    parameters: [["Distanza: km / nm", "Converte l'inserimento e le letture tra chilometri e miglia nautiche."], ["Velocità: kt / mph / km/h", "Converte i valori degli strumenti, le letture, le legende e le finestre di moto. I valori vengono convertiti, non reinterpretati."], ["Temperatura: °C / °F", "Converte la temperatura superficiale del mare nella legenda e nella lettura. Il livello contiene °C; cambia solo ciò che viene mostrato."], ["Frecce / Barbe del vento", "Controlli di stile e anteprime separati per ciascun tipo di simbolo."], ["Dimensione (%)", "Lunghezza del simbolo in percentuale della sua dimensione normale sullo schermo, dal 25% al 300%."], ["Densità", "Numero e spaziatura dei simboli. Una densità maggiore mostra più direzioni locali ma può affollare la mappa."], ["Spessore della linea", "Spessore dell'asta e delle barbe."], ["Colore / Opacità", "Colore del simbolo e trasparenza complessiva."], ["Attenua in base alla velocità", "Riduce l'opacità nel flusso più lento, lasciando visibile il vento in calma definito."], ["Ombra", "Aggiunge contrasto dietro i simboli."], ["Colore / opacità dell'ombra", "Colore e trasparenza indipendenti per l'ombra."], ["Ombra X / Y (px)", "Spostamento orizzontale e verticale dell'ombra in pixel."], ["Ripristina frecce / Ripristina barbe del vento", "Ripristina l'aspetto predefinito di quello stile."], ["Scale di colori del progetto", "Velocità massime fisse di vento/corrente quando Scala automatica è disattivata."], ["Gradienti del progetto", "Mappe di colori separate per vento e corrente, scelte tra i campioni."], ["Valori predefiniti per i nuovi progetti", "Limiti di scala iniziali di vento/corrente per i progetti creati in seguito."], ["Scorciatoie", "Fare clic su un'assegnazione, poi premere la combinazione che la sostituisce. Le assegnazioni mostrate descrivono la configurazione corrente."], ["Salvataggio automatico / libreria di macro", "Scegliere ripristino, salvataggio diretto o salvataggio manuale. Impostare la cartella delle macro o eliminare voci della libreria. L'eliminazione dalla libreria chiede conferma e conserva le macro già inserite nei progetti."], ["Servizio MCP", "Consente a un client di IA su questo computer di controllare l'applicazione tramite il Model Context Protocol. Disattivato per impostazione predefinita; quando è attivo, la sezione mostra l'indirizzo locale e il token. Aggiungi a Claude Code e Aggiungi a Codex scrivono il servizio nella configurazione del client stesso; dopo un token rinnovato o una porta cambiata, lo stesso pulsante la aggiorna. Aggiungi a Claude Desktop apre un'estensione di VectorEffects nel programma di installazione di Claude Desktop, dove va confermata; si installa una sola volta e segue da sola un nuovo token o una nuova porta. Configurazione per altri client contiene le stesse informazioni come testo da copiare. Rinnova token revoca quello precedente. La barra di stato mostra MCP e l'ultimo strumento mentre un client è connesso."]],
    images: [{ path: "settings.png", caption: "Controlli di aspetto separati per frecce e barbe del vento." }], related: ["view", "projects", "macros"] },
  { id: "export", group: "Impostazioni ed esportazione", title: "Esporta GRIB2", paragraphs: ["Esporta GRIB… scrive i vettori valutati per altre applicazioni. La finestra chiede l'inizio della previsione e, al momento dell'esportazione, la destinazione. I selettori del centro di origine e della precisione sono stati rimossi. Ogni messaggio riporta «Created with VectorEffects».", "L'esportazione usa la griglia del progetto indipendentemente da zoom, dimensione dello schermo e densità dei simboli. Conservare il file .veproj per continuare a modificare."],
    parameters: [["Scegli la posizione ed esporta…", "Chiede il percorso del file .grib2 di uscita e avvia l'esportazione."], ["Inizio della previsione (UTC)", "Ora di riferimento della previsione: anno, mese, giorno e ora. Gli scostamenti dei fotogrammi vengono sommati per ottenere le ore di validità dei messaggi; verificarle rispetto al periodo storico o di previsione previsto."], ["Dimensione stimata", "Un limite superiore. I campi sparsi e costanti possono essere molto più piccoli."], ["Avanzamento / Annulla l'esportazione", "Segnala l'avanzamento dell'esportazione, o la interrompe senza modificare il progetto."], ["Dati non definiti", "Le celle non coperte usano le bitmap GRIB. Non vengono scritte come zero. La calma dipinta deliberatamente resta uno zero definito."], ["Vento e corrente", "u e v vengono scritti separatamente per ogni fotogramma e ogni tipo di campo visibile. I livelli nascosti non contribuiscono."], ["Nota", "Ogni messaggio contiene «Created with VectorEffects» nella sua sezione per uso locale. Un lettore potrebbe non mostrarlo nei normali controlli di previsione."], ["Compressione automatica", "Compressione semplice standard a 16 bit, con campi costanti compatti. Non è necessario scegliere la precisione."], ["Contenuti della vista esclusi", "Mappa di base, immagini, simboli, maniglie di selezione e misurazioni non diventano vettori."], ["Esporta Zarr…", "Scrive gli stessi vettori valutati come cartella Zarr V3, nella struttura di routing: un array di dati Float16 di u10, v10, ucur e vcur con coordinate di tempo, parametro, latitudine e longitudine, con la latitudine a partire da 90° e la longitudine da -180°. I blocchi sono di tre giorni per 10 gradi, compressi con Zstd e raggruppati in shard per bacino oceanico; le celle non coperte sono NaN e una regione senza dati non viene scritta affatto."]],
    images: [{ path: "export.png", caption: "La finestra di esportazione semplificata, con l'ora di riferimento UTC e la scelta della destinazione." }],
    related: ["projects", "layers", "imports", "troubleshooting"] },
  { id: "troubleshooting", group: "Impostazioni ed esportazione", title: "Risoluzione dei problemi", paragraphs: ["Controllare prima il livello attivo, il fotogramma selezionato e il tipo di campo. Annulla aiuta a isolare una modifica recente. Salvare una copia prima di indagare su un progetto complesso."],
    parameters: [["Non appare nulla", "Controllare visibilità, blocco, durata dell'oggetto e filtri di velocità. Gli strumenti di modifica richiedono dati definiti sotto di essi. Un'Intensità neutra o una selezione di Trasla senza spostamento non fanno nulla."], ["Primo clic dopo un'impostazione", "La successiva pressione normale conferma l'inserimento numerico e usa lo strumento. Scegli sulla mappa, la cattura e il contagocce riservano il clic alla loro azione indicata."], ["Clone vuoto", "I vettori di origine devono trovarsi sotto il clone nello stesso livello. Un'origine vuota resta trasparente; la calma definita viene comunque copiata."], ["La divergenza sembra invertita", "Le barbe puntano verso il vento in arrivo. La divergenza piega il flusso reale verso l'esterno; la convergenza verso l'interno."], ["L'oggetto non è più nel progetto", "Annulla o un'eliminazione possono rimuovere la selezione. Le selezioni obsolete e le risposte delle proprietà ora vengono scartate. Se una modifica reale continua a non riuscire, selezionare di nuovo la riga corrente dell'oggetto."], ["Riproduzione lenta dei dati importati", "Attendere la barra di preparazione. Le letture iniziali degli archivi e la valutazione possono ritardare i passi/s richiesti."], ["Download storico non riuscito", "Usare Riprova il download accanto all'errore. Se l'archivio resta non disponibile, controllare il periodo richiesto e la connessione."], ["Origine mancante / progetto recente", "Ripristinare il percorso a cui si fa riferimento, o usare Apri… / Importa per ritrovarlo. I percorsi di progetto mancanti vengono rimossi dall'elenco dei recenti."], ["Scadenza della beta", "Questa beta scade il 1° gennaio 2027, in base alla data di sistema. Installare una versione aggiornata per continuare."]],
    related: ["layers", "clone", "divergence", "history", "export"] },
];

export default topics;
